const item = $input.first().json;
const ag = item.agendamento || {};
const lead = ag.lead || {};
const tenant = item.tenant || {};
const config = item.config || {};

const digits = (lead.telefone || '').replace(/\D/g, '');
const phoneWA = digits.length >= 10 ? (digits.startsWith('55') ? digits : '55' + digits) : '';

const parts = (ag.data || '').split('-');
const dataFormatada = parts.length === 3 ? parts[2] + '/' + parts[1] + '/' + parts[0] : ag.data;

const evolutionBaseUrl = tenant.evolutionBaseUrl || 'https://api.divulgabr.com.br';
const evolutionInstance = tenant.evolutionInstance || 'divulgabr';
const evolutionApiKey = tenant.evolutionApiKey || '9015A0349CE0-4C04-B429-4A0FA18BCE96';

return [{ json: {
  phoneWA,
  dataFormatada,
  hora: ag.hora || '',
  tipo: ag.tipo || 'consulta',
  canalOrigem: ag.canalOrigem || '',
  leadNome: lead.nome || '',
  leadTelefone: lead.telefone || '',
  servicoNome: ag.servico?.nome || '',
  tenantNome: tenant.nome || '',
  nichoLabel: tenant.nichoLabel || 'atendimento',
  apiToken: tenant.apiToken || '',
  whatsappAdmin: config.whatsappAdmin || '',
  agendamentoId: ag.id,
  evolutionBaseUrl,
  evolutionInstance,
  evolutionApiKey,
}}];

const norm = $('Normalizar Dados').first().json;
const cfg = $input.first().json;

function interpolar(template, vars) {
  return template
    .replace(/\{\{nome\}\}/g, vars.nome)
    .replace(/\{\{data\}\}/g, vars.data)
    .replace(/\{\{hora\}\}/g, vars.hora)
    .replace(/\{\{servico\}\}/g, vars.servico)
    .replace(/\{\{nicho\}\}/g, vars.nicho);
}

const vars = {
  nome: norm.leadNome,
  data: norm.dataFormatada,
  hora: norm.hora,
  servico: norm.servicoNome || norm.tipo,
  nicho: cfg.nichoLabel || norm.nichoLabel || 'atendimento',
};

const tplCliente = cfg.mensagemWaConfirmacao
  || '✅ Agendamento confirmado!\n\n📅 Data: {{data}}\n🕐 Horário: {{hora}}\n🏢 ' + norm.tenantNome + '\n\nSeu {{nicho}} está confirmado. Até lá!';

const tplAdmin = cfg.mensagemWaAdmin
  || '📅 Novo agendamento!\n\n👤 {{nome}}\n📱 ' + norm.leadTelefone + '\n📅 {{data}} às {{hora}}\n📋 {{nicho}}';

return [{ json: {
  ...norm,
  nichoLabel: vars.nicho,
  evolutionBaseUrl: cfg.evolutionBaseUrl || norm.evolutionBaseUrl,
  evolutionInstance: cfg.evolutionInstance || norm.evolutionInstance,
  evolutionApiKey: cfg.evolutionApiKey || norm.evolutionApiKey,
  msgCliente: interpolar(tplCliente, vars),
  msgAdmin: interpolar(tplAdmin, vars),
}}];

const data = $input.first().json;
const lembretes = data.lembretes || [];
if (lembretes.length === 0) return [];
return lembretes.map(l => {
  const parts = (l.data || '').split('-');
  const dataFormatada = parts.length === 3 ? parts[2] + '/' + parts[1] + '/' + parts[0] : l.data;
  return { json: { ...l, dataFormatada } };
});

const cfg = $input.first().json;
let item = {};
try { item = $('Converter para Items').item.json; } catch(e) {}

if (!item.phoneWA) return [];

const tipoLembrete = item.tipoLembrete || 'dia';

const vars = {
  nome: item.leadNome || '',
  data: item.dataFormatada || '',
  hora: item.hora || '',
  servico: '',
  nicho: cfg.nichoLabel || item.nichoLabel || 'atendimento',
};

const prefixos = {
  '3d':  '⏰ Lembrete: você tem um {{nicho}} em 3 dias!\n\n',
  '1d':  '⏰ Lembrete: seu {{nicho}} é amanhã!\n\n',
  'dia': '⏰ Lembrete: seu {{nicho}} é hoje!\n\n',
};

const tpl = cfg.mensagemWaLembrete
  || (prefixos[tipoLembrete] || prefixos['dia']) + '📅 {{data}} às {{hora}}\n\nSe precisar cancelar, entre em contato.';

const msgLembrete = tpl
  .replace(/\{\{nome\}\}/g, vars.nome)
  .replace(/\{\{data\}\}/g, vars.data)
  .replace(/\{\{hora\}\}/g, vars.hora)
  .replace(/\{\{servico\}\}/g, vars.servico)
  .replace(/\{\{nicho\}\}/g, vars.nicho);

const evolutionBaseUrl = cfg.evolutionBaseUrl || item.evolutionBaseUrl || 'https://api.divulgabr.com.br';
const evolutionInstance = cfg.evolutionInstance || item.evolutionInstance || 'divulgabr';
const evolutionApiKey = cfg.evolutionApiKey || item.evolutionApiKey || '9015A0349CE0-4C04-B429-4A0FA18BCE96';

return [{ json: { ...item, tipoLembrete, apiToken: item.apiToken || '', msgLembrete, evolutionBaseUrl, evolutionInstance, evolutionApiKey } }];
